"""Time-frequency trade-off: narrowing a box broadens its sinc transform."""
from __future__ import annotations
import numpy as np


def effective_support(width: float, threshold: float = 0.05) -> float:
    """Effective support (measure of {|transform| > threshold*peak}) of w*sinc(w*k)."""
    k = np.linspace(-200, 200, 400001)
    with np.errstate(divide="ignore", invalid="ignore"):
        trans = np.where(k == 0, width, np.sin(np.pi * width * k) / (np.pi * k))
    peak = np.abs(trans).max()
    return float(np.sum(np.abs(trans) > threshold * peak) * (k[1] - k[0]))


def main() -> None:
    for w in (4.0, 2.0, 1.0, 0.5, 0.25):
        print(f"box width {w:>5}: effective transform support = {effective_support(w):.2f}")


if __name__ == "__main__":
    main()
